  'aiworkspace.demo.quarterly.introText': 'Esta es una tabla de ventas normal del 2T de 2026: ingresos, costes, objetivo e ingresos del trimestre anterior por región y producto. Puedes cambiar las cifras directamente en el modo de fuente de datos, o describir en una frase el análisis que quieres en el bloque de deseo del lienzo y pulsar su botón tres veces: Analizar, Escribir macro y Ejecutar macro. Cada paso escribe su resultado en cuanto termina; si alguno no es lo que querías, vuelve a la pestaña anterior y ejecútalo de nuevo, o revierte. La flecha azul discontinua muestra lo que lee el deseo y las naranjas, lo que creó. Cuando cambien los datos, ejecuta la macro otra vez.',
