  'aiworkspace.demo.film.script.title': 'Esquema del guion: La mensajera de la noche de lluvia',
  'aiworkspace.demo.film.script.logline': 'Sinopsis: en una noche de tormenta, el mensajero Che y el robot Xiaoman deben entregar un paquete misterioso en el punto más alto de la ciudad antes del amanecer.',
  'aiworkspace.demo.film.script.scenes': 'Escenas',
  'aiworkspace.demo.film.script.scene1': '1. Azotea · noche · lluvia: Che recibe un pedido urgente; Xiaoman lee en voz alta «Destino: Torre Cloudtop». (Che, Xiaoman)',
  'aiworkspace.demo.film.script.scene2': '2. Calle de neón · noche: los dos se abren paso por un mercado nocturno abarrotado, esquivando drones de patrulla. (Che, Xiaoman)',
  'aiworkspace.demo.film.script.scene3': '3. Tienda de fideos de Zhou · noche: Zhou entrega un cuenco de fideos calientes y revela el secreto del paquete. (Che, Zhou)',
  'aiworkspace.demo.film.script.scene4': '4. Paso elevado · noche · lluvia: persecución de drones; Xiaoman salva a Che con su brazo magnético. (Che, Xiaoman)',
  'aiworkspace.demo.film.script.scene5': '5. Cima de la Torre Cloudtop · amanecer: el paquete se abre y dentro hay una semilla luminosa. (Che, Xiaoman, Zhou)',
  'aiworkspace.demo.film.script.scene6': '6. Azotea · salida del sol: la ciudad despierta mientras los dos comen fideos y ven el amanecer. (Che, Xiaoman)',
  'aiworkspace.demo.film.style.summary': 'Estilo: ciberpunk × acuarela, con cian neón y morado como colores principales, grano de película y formato panorámico cinematográfico 16:9',
  'aiworkspace.demo.film.style.night': 'Las escenas nocturnas son mayormente frías; los colores cálidos solo aparecen en la tienda de fideos y al amanecer',
