  'aiworkspace.demo.film.styleName': 'Estilo visual',
  'aiworkspace.demo.film.howtoName': 'Cómo usar este lienzo',
  'aiworkspace.demo.film.howto.title': 'Flujo de trabajo de un cortometraje con IA: fichas de personajes → ilustraciones de personajes → storyboard → montaje final',
  'aiworkspace.demo.film.howto.text': 'Un flujo de generación de izquierda a derecha en el que cada nodo es un objeto normal del lienzo: a la izquierda están el guion, la tabla de personajes y el estilo, que puedes editar directamente; cada etapa es un bloque de deseo y, en cada tarjeta, pulsas por turno Analizar, Escribir macro y Ejecutar macro: cada paso escribe su resultado en cuanto termina. Lo que produce una etapa es la entrada de la siguiente, así que ejecuta las etapas de izquierda a derecha; las flechas azules discontinuas parten de lo que lee un deseo y las naranjas llegan a lo que creó. Si cambias la tabla de personajes o el guion, los resultados posteriores se marcan como desactualizados; vuelve a ejecutarlos uno tras otro. Las imágenes y el vídeo los generan los modelos de IA de la Zone.',
  'aiworkspace.demo.film.surface': 'Flujo del cortometraje',
  'aiworkspace.demo.film.wish1.title': 'Bloque de deseo ①: generar las hojas de personaje',
  'aiworkspace.demo.film.wish1.prompt': 'A partir de la tabla «{{characters}}» y de «{{style}}», genera una hoja de personaje en vertical para cada personaje, con una breve nota de perfil. Conserva el color principal y los accesorios de cada personaje para que el storyboard pueda referirse a ellos más adelante.',
  'aiworkspace.demo.film.wish1.output': 'Hojas de personaje',
  'aiworkspace.demo.film.wish2.title': 'Bloque de deseo ②: generar el storyboard',
  'aiworkspace.demo.film.wish2.prompt': 'A partir de las escenas de «{{script}}», junto con «{{sheets}}» y «{{style}}», genera un storyboard: un plano por escena; devuelve una lista de planos (n.º de plano, escena, tipo de plano, personajes, acción, duración) y un fotograma para cada plano.',
  'aiworkspace.demo.film.wish2.output': 'Storyboard',
  'aiworkspace.demo.film.wish3.title': 'Bloque de deseo ③: generar la vista previa del montaje final',
  'aiworkspace.demo.film.wish3.prompt': 'A partir de «{{storyboard}}», genera un vídeo de vista previa del montaje final: un único clip continuo de unos 8 segundos (16:9) que siga los planos en el orden de la lista, con el fotograma del primer plano como imagen de referencia; escribe también una nota con el número de planos y la duración total de la lista de planos.',
  'aiworkspace.demo.film.wish3.output': 'Montaje final',
